// Block (composition) — a sheet that narrows a list to a numeric range: a range slider on a sunken
// panel, then named presets that each set the range in one press ("15GB · 출퇴근길에 영상을 본다면"),
// and a footer that resets the range or shows the results. It opens as a bottom sheet on a phone and a
// centred panel on a wide screen.
//
// The range is controlled: the consumer holds `value` and counts the matches for `submitLabel`, so
// the button can say how many results it will show before it is pressed. A preset is chosen while
// the range equals its own, so dragging the slider off a preset clears the choice, and the radio
// group reads that state rather than keeping a second one.
//
// Drawer owns the overlay, Slider the range, RadioGroup the presets, Button the actions; this Block
// only arranges them.
import type { ReactNode } from "react";
import {
  DrawerContent,
  DrawerDescription,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
  DrawerTrigger,
} from "../components/Drawer";
import { Button } from "../components/Button";
import { Card } from "../components/Card";
import { Undo } from "../components/icons";
import { Radio, RadioGroup } from "../components/RadioGroup";
import { Slider } from "../components/Slider";
import { Stack } from "../layouts/Stack";
import "./RangeFilterSheet.css";

export interface RangePreset {
  /** Stable key. */
  id: string;
  /** The preset's value as read, e.g. "15GB". */
  label: string;
  /** Who the preset suits, e.g. "출퇴근길에 영상을 본다면". */
  description?: string;
  /** The range the preset sets, inclusive. */
  range: [number, number];
}

export interface RangeFilterSheetProps {
  /** Control that opens the sheet. */
  trigger: ReactNode;
  /** Sheet heading. */
  title: string;
  /** One line under the heading saying what the range narrows. */
  description?: string;
  /** Accessible name of the close (X) button, for a screen that is not in English.
      @default "Close" */
  closeLabel?: string;
  /** How the sheet attaches to the viewport, forwarded to DrawerContent: `inset` is a floating
   *  card, `full-bleed` a bottom sheet that touches the screen's edges. A product picks one for every
   *  sheet it shows.
   * @default "inset"
   */
  variant?: "inset" | "full-bleed";
  /** The slider's label, e.g. "월 데이터". */
  label: string;
  /** Lowest value the slider reaches. */
  minValue: number;
  /** Highest value the slider reaches. */
  maxValue: number;
  /** Slider step.
   * @default 1
   */
  step?: number;
  /** How the slider writes its values, e.g. `{ style: "unit", unit: "gigabyte" }`. */
  formatOptions?: Intl.NumberFormatOptions;
  /** What the slider's readout says for a range, e.g. "모든 용량" for the whole scale. */
  getValueLabel?: (value: [number, number]) => string;
  /** The chosen range. */
  value: [number, number];
  /** Called with the new range, from the slider, a preset, or reset. */
  onChange: (value: [number, number]) => void;
  /** Ranges the reader can pick by name, in the order they show. */
  presets?: RangePreset[];
  /** The submit action's label; say what it shows, e.g. "1,989개 결과 보기". */
  submitLabel: string;
  /** Called when the reader asks for the results. The sheet then closes. */
  onSubmit?: () => void;
  /** The reset action's label. It returns the range to the whole scale.
   * @default "Reset"
   */
  resetLabel?: string;
}

const same = (a: [number, number], b: [number, number]) => a[0] === b[0] && a[1] === b[1];

export function RangeFilterSheet({
  trigger,
  title,
  description,
  closeLabel,
  variant,
  label,
  minValue,
  maxValue,
  step = 1,
  formatOptions,
  getValueLabel,
  value,
  onChange,
  presets = [],
  submitLabel,
  onSubmit,
  resetLabel = "Reset",
}: RangeFilterSheetProps) {
  const chosen = presets.find((p) => same(p.range, value));
  const whole = value[0] === minValue && value[1] === maxValue;

  return (
    <DrawerTrigger>
      {trigger}
      <DrawerContent
        variant={variant}
        side="sheet"
        className="sd-rangefiltersheet"
        closeLabel={closeLabel}
        header={
          <DrawerHeader>
            <DrawerTitle>{title}</DrawerTitle>
            {description && <DrawerDescription>{description}</DrawerDescription>}
          </DrawerHeader>
        }
        footer={
          <DrawerFooter layout="fill">
            {/* usage: completing-action — returns the range to the whole scale, the sheet stays open */}
            <Button size="large" variant="secondary" isDisabled={whole} onPress={() => onChange([minValue, maxValue])}>
              <Undo aria-hidden size="1em" />
              {resetLabel}
            </Button>
            {/* usage: completing-action — shows the results and closes the sheet */}
            <Button size="large" variant="primary" slot="close" onPress={onSubmit}>
              {submitLabel}
            </Button>
          </DrawerFooter>
        }
      >
        <Stack gap="medium">
          <Card variant="sunken">
            <Slider
              label={label}
              minValue={minValue}
              maxValue={maxValue}
              step={step}
              formatOptions={formatOptions}
              getValueLabel={getValueLabel && ((v) => getValueLabel([v[0], v[1]]))}
              value={value}
              onChange={(v) => onChange(v as [number, number])}
            />
          </Card>
          {presets.length > 0 && (
            <RadioGroup
              variant="filled"
              aria-label={label}
              value={chosen?.id ?? null}
              onChange={(id) => {
                const preset = presets.find((p) => p.id === id);
                if (preset) onChange(preset.range);
              }}
            >
              {presets.map((preset) => (
                <Radio key={preset.id} value={preset.id}>
                  <span className="sd-rangefiltersheet__preset">
                    <strong className="sd-type-body-medium-emphasized">{preset.label}</strong>
                    {preset.description && <span className="sd-rangefiltersheet__hint sd-type-caption-medium">{preset.description}</span>}
                  </span>
                </Radio>
              ))}
            </RadioGroup>
          )}
        </Stack>
      </DrawerContent>
    </DrawerTrigger>
  );
}

/* RangeFilterSheet.css — .sd-rangefiltersheet (Block)
   Arrangement only. Drawer owns the sheet, Card the sunken panel, Slider and RadioGroup their
   controls. A preset reads as its value, then who it suits beside it. */
.sd-rangefiltersheet__preset {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: var(--sd-space-2x-small) var(--sd-space-small);
}

/* The hint annotates the value beside it (naming-convention.md, text colour row 4). */
.sd-rangefiltersheet__hint {
  color: var(--sd-color-text-muted);
}
